 for r in top:
  source=r['source'];p=pm.loc[source,'lag_5_autocorrelation'] if source in pm.index else None;a=rb.loc[source] if source in rb.index else None
  lines.append('| '+ ' | '.join([source,r['family'],r['PIT'],r['Timing'],r['Novelty'],fmt(p),f"{fmt(a.agreement)} / {fmt(a.Spearman)}" if a is not None else 'UNMEASURED',r['access'],str(r['score'])+'/20',str(r['hard_gates_pass'])])+' |')
 lines+=['', 'A score is source quality, not forecasting performance. SPD alignment contributes at most 2/20. Missing state access receives no invented alignment or novelty benefit. Inclusion in the shortlist never overrides hard PIT, rights, history or novelty gates.','', '## Same/as-of frozen SPD alignment','', '| Source | Cells | Origins | SPD releases | Candidate states | Agreement | Balanced agreement | Weighted Spearman |','|---|---|---|---|---|---|---|---|']
 for source,a in rb.iterrows():lines.append('| '+' | '.join([source,str(int(a.cells)),str(int(a.origins)),str(int(a.SPD_releases)) if pd.notna(a.get('SPD_releases')) else 'N/A',str(int(a.candidate_states)) if pd.notna(a.get('candidate_states')) else 'N/A',fmt(a.agreement),fmt(a.balanced_agreement),fmt(a.Spearman)])+' |')
